    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void UnixRaw_TwoRows_AreWrittenAsOneOrderedFrame ()
    {
        List<byte []> writes = [];
        AnsiOutput output = new (bytes =>
        {
            writes.Add (bytes.ToArray ());
            return true;
        });
        OutputBufferImpl buffer = new ();
        buffer.SetSize (2, 2);
        buffer.Move (0, 0);
        buffer.AddStr ("AB");
        buffer.Move (0, 1);
        buffer.AddStr ("CD");

        output.Write (buffer);

        Assert.Single (writes);
        string actual = Encoding.UTF8.GetString (writes [0]);
        int firstMove = actual.IndexOf (EscSeqUtils.CSI_SetCursorPosition (1, 1), StringComparison.Ordinal);
        int firstText = actual.IndexOf ("AB", StringComparison.Ordinal);
        Assert.True (firstMove >= 0 && firstText > firstMove);
        Assert.Contains (EscSeqUtils.CSI_SetCursorPosition (2, 1) + "CD", actual);
        Assert.Equal (actual, output.GetLastOutput ());
    }

    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void UnixRaw_OnlyLastDeferredCursorMoveIsSent ()
    {
        List<byte []> writes = [];
        AnsiOutput output = new (bytes =>
        {
            writes.Add (bytes.ToArray ());
            return true;
        });
        OutputBufferImpl buffer = new ();
