    }

    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void UnixRaw_CharWriteDuringFrame_FollowsDeferredCursorMove ()
    {
        List<byte []> writes = [];
        InjectingCursorOutput output = new (bytes =>
        {
            writes.Add (bytes.ToArray ());
            return true;
        });
        OutputBufferImpl buffer = new ();
        buffer.SetSize (1, 1);
        buffer.AddStr ("X");

