    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void UnixRaw_KittyHyperlinkAndSixel_KeepTheirOrder ()
    {
        List<byte []> writes = [];
        AnsiOutput output = new (bytes =>
        {
            writes.Add (bytes.ToArray ());
            return true;
        }) { UseKittyGraphics = true };
        OutputBufferImpl buffer = new ();
        buffer.SetSize (3, 1);
        buffer.Clip = new Region (new Rectangle (0, 0, 3, 1));
        buffer.AddRasterImage (new RasterImageCommand
        {
            Id = "image",
            Pixels = new Color [1, 1] { { new (255, 0, 0) } },
            DestinationCells = new Rectangle (2, 0, 1, 1)
        });
        buffer.CurrentUrl = "https://example.org/路径";
        buffer.AddStr ("é");
        output.GetSixels ().Enqueue (new SixelToRender
        {
            SixelData = "\u001bPq#0~\u001b\\",
            ScreenPosition = new (0, 0)
        });

        output.Write (buffer);

        string actual = Encoding.UTF8.GetString (writes.SelectMany (bytes => bytes).ToArray ());
        int kitty = actual.IndexOf ("\u001b_G", StringComparison.Ordinal);
        int hyperlink = actual.IndexOf ("https://example.org/路径", StringComparison.Ordinal);
        int sixel = actual.IndexOf ("\u001bPq", StringComparison.Ordinal);
        Assert.True (kitty >= 0 && hyperlink > kitty && sixel > hyperlink);
        Assert.Equal (actual, output.GetLastOutput ());
    }

