    private class LegacyStringWriter : OutputBase
    {
        public StringBuilder Written { get; } = new ();

        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;

        protected override void Write (StringBuilder output) => Written.Append (output);
    }

    private sealed class LegacyAttributeWriter : LegacyStringWriter
    {
        protected override void AppendOrWriteAttribute (StringBuilder output,
                                                        Terminal.Gui.Drawing.Attribute attr,
                                                        TextStyle redrawTextStyle) => output.Append ("<attribute>");
    }

    private sealed class InjectingCursorOutput : AnsiOutput
    {
        private bool _injected;

        public InjectingCursorOutput (UnixWriter writer) : base (writer) { }

        protected override bool SetCursorPositionImpl (int col, int row)
        {
            bool moved = base.SetCursorPositionImpl (col, row);

            if (_injected)
            {
                return moved;
            }

            _injected = true;
            Write ("M".AsSpan ());
            return moved;
        }
    }

    private sealed class ThrowingCursorOutput : AnsiOutput
    {
        private bool _throw = true;

        public ThrowingCursorOutput (UnixWriter writer) : base (writer) { }

        protected override bool SetCursorPositionImpl (int col, int row)
        {
            bool moved = base.SetCursorPositionImpl (col, row);

            if (_throw)
            {
                _throw = false;
                throw new InvalidOperationException ("render failure");
            }

            return moved;
        }
    }

    private sealed class ExposedNetOutput : NetOutput
    {
        public void WriteBytes (ReadOnlySpan<byte> bytes) => Write (bytes);
    }

    private sealed class ExposedWindowsOutput : WindowsOutput
    {
        public void WriteBytes (ReadOnlySpan<byte> bytes) => Write (bytes);
    }
}
